 def solver(testcase, N=None, P=None, I=None, T=None, S=None, C=None, **ignore):
     ########= P
     #print '--', R, C, M
     MM = M

     F = np.array([['.'] * C] * R)
     while M > 0:
         # reduce if possible
         if R >= C and M >= C and R > 2:
             M -= C
             R -= 1
             F[R] = '*'
         elif C > R  and M >= R and C > 2:
             M -= R
             C -= 1
             F[:, C] = '*'
         # solve simple
         elif R > 2 and C > 2 and (R > 3 or C > 3 or M == 1):
             if M < C - 1:
                 R -= 1
                 F[R, C - M:C] = '*'
             elif M < R - 1:
                 C -= 1
                 F[R - M:R, C] = '*'
             elif M == C - 1:
                 R -= 1
                 F[R, C - M + 1:C] = '*'
                 F[R - 1, C - 1] = '*'
             else:
                 C -= 1
                 F[R - M + 1:R, C] = '*'
                 F[R - 1, C - 1] = '*'
             M = 0
         #Â special cases
         elif M == R * C - 1:
             F[:, :] = '*'
             M = 0
         else:
             #print F
             #print R, C, M
             return 'Case #%s:\n%s\n' % (testcase, 'Impossible')

     F[0, 0] = 'c'
     assert (F == '*').sum() == MM
     return 'Case #%s:\n%s\n' % (testcase, '\n'.join(''.join(f.tolist()) for f in F))

