 def war_answer_simulator(blocks, choice):
 	over_arr = []
 	for elem in blocks:
 		if elem > choice:
 			over_arr.append(elem)
 	if not over_arr:
 		return min(blocks)
 	return min(over_arr)

 def war_counter(a, b):
 	count = 0
 	while len(a) and len(b):
 		if a[0] > b[0]:
 			count += 1
 		else:
 			b.pop(0)
 		a.pop(0)
 	return count

 def dec_counter(a, b):
 	count = 0
