 def getNumRecycle(n,A,B,h):
         c=0
         x=list(str(n))
         for i in xrange(1,len(x)):
             t1="".join(x[0:i])
             t2="".join(x[i:len(x)])
             num=int(t2+t1)
             if((num>=A and num<=B) and num<>n and h.get((num,n))==None and h.get((n,num))==None):
                 #print "(",str(n),",",str(num),")"
                 h[(num,n)]=0;
                 c+=1
         return c


